function updateLanes(){let active=data.active_pairs||[],keys=new Set(active.map(e=>e.stage+':'+e.index));for(let l of lanes)if(l.key&&!keys.has(l.key)){l.key=null;l.event=null;l.view.ids=[];l.box.classList.remove('busy');l.view.dirty=true}makeLanes(active.length);for(let e of active){let key=e.stage+':'+e.index,l=lanes.find(l=>l.key===key)||lanes.find(l=>!l.key);if(!l)continue;if(l.key!==key){l.key=key;l.event=e;l.view.ids=[e.object_a,e.object_b];l.view.fit(l.view.ids);l.status.textContent='计算中';l.note.textContent=l.view.ids.map(id=>short(id)+' '+identity(id)).join(' ↔ ');l.box.classList.add('busy')}}$('activeCount').textContent=active.length;$('parallelNote').textContent=active.length?'正在计算 '+active.length+' 对；显示 '+lanes.length+' 对':'暂无活跃精确计算（准备中 / 本轮结束）';const configured=state.resident?.workers||[...(state.events||[])].reverse().find(e=>e.max_workers)?.max_workers;if(['RUNNING','PAUSING'].includes(state.status)&&configured)$('workers').value=configured;if($('follow').checked&&active.length){const e=active[0],key=e.stage+':'+e.index;if(lastFollow!==key){lastFollow=key;choose([e.object_a,e.object_b],null,false)}}}
async function loadPreview(version){if(loadingPreview||version===previewVersion)return;loadingPreview=true;try{$('previewNote').textContent='正在加载显示网格…';const response=await fetch(base+'/preview');if(!response.ok)throw Error('预览尚未就绪');mesh=await response.json();byId=new Map();for(const o of mesh.objects){o.exact_bounds=o.bounds;const display=displayBounds(o.vertices);if(display)o.bounds=display;if(!o.bounds){let min=[Infinity,Infinity,Infinity],max=[-Infinity,-Infinity,-Infinity];for(let i=0;i<o.vertices.length;i++){let axis=i%3;min[axis]=Math.min(min[axis],o.vertices[i]);max[axis]=Math.max(max[axis],o.vertices[i])}o.bounds={min,max}}byId.set(o.id,o)}mesh.bounds=boundsFor(mesh.objects.map(o=>o.id));mainView.reset();for(const l of lanes)l.view.reset();previewVersion=version;$('previewNote').textContent=mesh.objects.length+' 实体 · '+mesh.triangle_count.toLocaleString()+' 三角面 · '+(mesh.truncated?'存在截断':'无截断')+(mesh.triangle_count<600000?' · 旧粗网格，精细版生成后自动更新':' · 精细网格');renderObjects()}catch(e){$('previewNote').textContent='网格加载失败：'+e.message}finally{loadingPreview=false}}
async function poll(){try{const response=await fetch(base+'/state');if(!response.ok)throw Error('监控服务不可用');state=await response.json();data=state.dashboard||{};const events=state.events||[],last=events.at(-1)||{},batch=events.findLast(e=>e.stage==='CATIA_BATCH_EXPORT_COMPLETE'),count=data.checkpoint_count||state.resume?.completed_pairs||0,total=data.candidate_count||0;const running=['RUNNING','PAUSING'].includes(state.status);$('pause').disabled=!state.pause_supported||state.status!=='RUNNING';$('pause').textContent=state.status==='PAUSING'?'正在保存并暂停…':'暂停';$('start').textContent=state.status==='PAUSED'?'继续检查':'开始 / 续跑';$('status').textContent=state.status==='PAUSING'?'正在暂停':state.status==='PAUSED'?'已暂停':running?'运行中':state.status==='ERROR'?'异常':state.status==='READY'?'待启动':state.resume?.needs_resume?'待续跑':'本轮结束';$('start').disabled=running;$('workers').disabled=running;$('budget').disabled=running;$('elapsed').textContent=Math.floor(state.elapsed_seconds/60)+' 分 '+state.elapsed_seconds%60+' 秒';$('batch').textContent=batch?batch.batch_number+' 批':'—';$('pairs').textContent=count+' / '+(total||'待确认');$('errors').textContent=(state.totals?.timeouts||0)+' / '+(state.totals?.errors||0);$('progress').style.width=(total?count/total*100:0)+'%';$('operation').textContent=(last.operation||({CATIA_BATCH_EXPORT_COMPLETE:'已完成一批 CATIA Body 临时导出',BATCH_LOAD_START:'OCCT 正在读取精确几何',BATCH_LOAD_COMPLETE:'精确几何读取完成',PREVIEW_START:'生成精细三维预览',PREVIEW_COMPLETE:'精细预览已就绪',CHECKPOINT_LOADED:'核对并读取续跑检查点',EXACT_PAIR_PRIMARY_START:'精确计算当前对象对',EXACT_PAIR_PRIMARY_COMPLETE:'对象对计算完成'})[last.stage]||last.stage||'等待任务')+(last.object_a?' · '+short(last.object_a)+' ↔ '+short(last.object_b):'');$('resultpath').textContent=state.result_path||'';$('log').replaceChildren(...events.slice(-60).reverse().map(e=>txt('div',e.time+' '+JSON.stringify(e))));pipelineProgress(events);renderResults();renderObjects();updateLanes();if(state.preview_ready)loadPreview(state.preview_version);else $('previewNote').textContent='等待 OCCT 三维网格'}catch(e){$('operation').textContent='连接中断：'+e.message}finally{setTimeout(poll,2000)}}
const eventPipelineProgress=pipelineProgress;
pipelineProgress=function(events){
 eventPipelineProgress(events);
 const p=state.export_progress;if(!p)return;
 const cards=pipeline.querySelectorAll('.pipelineStage');
 const paint=(card,done,total,note)=>{
  if(!card)return;card.querySelector('div').textContent=done+' / '+(total||'待确认')+' 项'+(total?' · '+(100*done/total).toFixed(1)+'%':'');
  const bar=card.querySelector('progress');bar.max=total||1;bar.value=done;
  card.querySelector('small').textContent=note;
 };
 paint(cards[0],p.body_done,p.body_total,p.body_batches+' 批实体文件已导出');
 paint(cards[1],p.surface_done,p.surface_total,p.surface_batches+' 批已落盘 · 导出错误 '+p.surface_errors+' · 最近更新 '+(p.updated_at||'等待')+(p.seconds_since_update!=null?'（'+p.seconds_since_update+' 秒前）':''));
 const phases=state.pipeline_counts;
 if(phases?.batch_total)paint(cards[2],phases.imported,phases.batch_total,phases.imported===phases.batch_total?'本轮精确几何导入已完成':'本轮按批导入中');
 if(phases?.preview_complete)paint(cards[3],1,1,'本轮三维网格已就绪');
 $('batch').textContent=p.body_batches+' 实体批 / '+p.surface_batches+' 面壳批';
 const importing=events.some(e=>['BATCH_LOAD_START','FULL_EXPORT_COMPLETE'].includes(e.stage));
 if(state.status==='RUNNING'&&!p.export_finished&&!importing){
  $('operation').textContent='CATIA 面／壳导出：'+p.surface_done+' / '+p.surface_total+' · 已落盘 '+short(p.latest_batch||'')+' · '+(p.latest_object||'正在复测源实体或准备下一批')+'；当前批内部进度未知';
  $('progress').style.width=(p.surface_total?100*p.surface_done/p.surface_total:0)+'%';
 }
 if(state.watch_only){$('start').disabled=true;$('pause').disabled=true;$('start').textContent='监控已有任务'}
};
function animate(now){const moving=mainView.tickTransition(now);if(!moving&&$('spin').checked){mainView.yaw+=.004;mainView.dirty=true}if(mainView.dirty)mainView.draw($('isolate').checked,$('wire').checked);for(const lane of lanes){const laneMoving=lane.view.tickTransition(now);if(!laneMoving&&lane.event&&$('spin').checked){lane.view.yaw+=.006;lane.view.dirty=true}if(lane.view.dirty){if(lane.event)lane.view.draw(true,$('wire').checked);else if(lane.view.gl){lane.view.gl.clearColor(.025,.05,.085,1);lane.view.gl.clear(lane.view.gl.COLOR_BUFFER_BIT);lane.view.dirty=false}}}requestAnimationFrame(animate)}
