$('focus').onclick=()=>mainView.fit(selected);$('iso').onclick=()=>mainView.transitionTo({yaw:.65,pitch:.3});$('front').onclick=()=>mainView.transitionTo({yaw:0,pitch:0});$('top').onclick=()=>mainView.transitionTo({yaw:0,pitch:Math.PI/2});$('zoomIn').onclick=()=>mainView.transitionTo({zoom:Math.min(80,(mainView.transition?.to.zoom||mainView.zoom)*1.25)});$('zoomOut').onclick=()=>mainView.transitionTo({zoom:Math.max(.05,(mainView.transition?.to.zoom||mainView.zoom)/1.25)});
let fullscreenResultState=null;
function restoreFullscreenResults(){
 if(!fullscreenResultState)return;
 const {results,placeholder,wasHidden}=fullscreenResultState;
 placeholder.replaceWith(results);results.hidden=wasHidden;fullscreenResultState=null;mainView.dirty=true;
}
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)restoreFullscreenResults();mainView.dirty=true});
$('fullscreen').onclick=async()=>{
 if(document.fullscreenElement){await document.exitFullscreen();return}
 const viewer=document.querySelector('.viewer'),results=document.querySelector('.results');
 const placeholder=document.createComment('fullscreen-results-position');results.before(placeholder);
 fullscreenResultState={results,placeholder,wasHidden:results.hidden};results.hidden=false;viewer.append(results);
 if(!$('fullscreenResultsStyle')){const style=document.createElement('style');style.id='fullscreenResultsStyle';style.textContent='.viewer:fullscreen{position:relative;width:100vw;height:100vh;overflow:auto;background:#111c2c;padding-right:calc(clamp(320px,35vw,540px) + 20px)}.viewer:fullscreen>.results{position:absolute;right:0;top:0;bottom:0;width:clamp(320px,35vw,540px);overflow:auto;border-radius:0}.viewer:fullscreen .viewport{height:calc(100vh - 300px);min-height:220px}.viewer:fullscreen .results .resultColumns{grid-template-columns:1fr}.viewer:fullscreen .results .resultList{height:210px}.viewer:fullscreen>.help{display:none}@media(max-width:700px){.viewer:fullscreen{padding-right:15px}.viewer:fullscreen>.results{position:relative;width:100%;height:auto}.viewer:fullscreen .viewport{height:50vh}}';document.head.append(style)}
 try{await viewer.requestFullscreen();mainView.dirty=true}catch(e){restoreFullscreenResults();$('operation').textContent='无法进入全屏：'+e.message}
};
for(const id of ['isolate','wire','showFailures','autoFocus','ghost','ghostOpacity'])$(id).oninput=()=>{if(id==='autoFocus'&&!$('autoFocus').checked&&mainView.transition?.origin==='automatic')mainView.transition=null;mainView.dirty=true;for(const l of lanes)l.view.dirty=true};$('follow').onchange=()=>{lastFollow='';updateLanes()};$('objectSearch').oninput=renderObjects;$('resultSearch').oninput=renderResults;$('policy').onchange=renderResults;$('volumeLimit').oninput=renderResults;$('geometryTab').onclick=()=>{inventoryMode='geometry';$('geometryTab').classList.add('active');$('catiaTab').classList.remove('active');$('geoTab').classList.remove('active');renderObjects()};$('catiaTab').onclick=()=>{inventoryMode='catia';$('catiaTab').classList.add('active');$('geometryTab').classList.remove('active');$('geoTab').classList.remove('active');renderObjects()};$('windowCount').onchange=()=>{makeLanes();updateLanes()};window.onresize=()=>{mainView.dirty=true;for(const l of lanes)l.view.dirty=true};document.onfullscreenchange=window.onresize;$('geoTab').onclick=()=>{inventoryMode='sets';$('geoTab').classList.add('active');$('geometryTab').classList.remove('active');$('catiaTab').classList.remove('active');renderObjects()};makeLanes();poll();requestAnimationFrame(animate);
